source.exploreUrl:
@js:
const list = [];
const html = java.ajax("https://101kks.com");

list.push({
    title: "标签-按更新排序？",
    url: "",
    style: { layout_flexGrow: 1, layout_flexBasisPercent: 1 }
});

// 精准匹配分类链接：限定/newtag/路径，兼容标签其他属性
const reg = /<a href="(\/newtag\/[^"]+)"[^>]*>([^<]+)<\/a>/g;
let match;
while ((match = reg.exec(html)) !== null) {
	const title = match[2].trim();
	// 路径规范化：去掉结尾斜杠后统一拼接分页格式
	const basePath = match[1].replace(/\/$/, '');
	list.push({
		title: title,
		url: `${basePath}/{{page}},{"webView":true}`,
		style: {
			layout_flexGrow: 1,
			layout_flexBasisPercent: 0.2
		}
	});
}

JSON.stringify(list);

